package app.launcherin.tv;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk={34,35}) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class LauncherinPresentationTest {
 Context c;LauncherinMusicProfiles profiles;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();profiles=new LauncherinMusicProfiles(c);}
 byte[] jpeg(int w,int h)throws Exception{Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);b.eraseColor(0xff527aad);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,85,out);b.recycle();return out.toByteArray();}
 String stagePhoto(byte[] bytes)throws Exception{String hash=LauncherinMusicLibrary.hash(bytes);try(FileOutputStream out=new FileOutputStream(LauncherinProfilePhotos.incoming(c,"mp-"+hash.substring(0,40)+".jpg"))){out.write(bytes);}return hash;}
 Bundle commit(String id,String name,String photo,String expected)throws Exception{JSONObject j=new JSONObject().put("id",id).put("name",name).put("photo",photo).put("expected",expected);byte[] bytes=j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(LauncherinProfilePhotos.incoming(c,LauncherinProfilePhotos.PENDING))){out.write(bytes);}return LauncherinProfilePhotos.call(c,"commitMusicProfile",LauncherinMusicLibrary.hash(bytes));}
 @Test public void photoAndNameUpdateIsAtomicAndDoesNotSwitchProfileOrChangeLibrary()throws Exception{LauncherinMusicLibrary library=new LauncherinMusicLibrary(c);library.toggle(LauncherinNativeMusicTest.track(1));library.progress(0,27000);String second=profiles.list().get(1).id;LauncherinMusicProfiles.Profile old=profiles.list().get(1);String hash=stagePhoto(jpeg(512,512));assertTrue(commit(second,"Perfil de exemplo",hash,LauncherinProfilePhotos.revision(old)).getBoolean("ok"));assertEquals("default",profiles.active().id);assertEquals(27000,library.position());assertEquals(1,library.read("favorites").size());assertEquals(hash,profiles.list().get(1).photo);assertNotNull(LauncherinProfilePhotos.avatar(c,profiles.list().get(1),96));profiles.rename(second,"Outro nome");assertEquals(hash,profiles.list().get(1).photo);}
 @Test public void invalidPhotoAndStaleRevisionKeepTheOldProfile()throws Exception{LauncherinMusicProfiles.Profile old=profiles.active();String bad=stagePhoto(new byte[]{(byte)255,(byte)216,0,0});assertFalse(commit(old.id,"Troca",bad,LauncherinProfilePhotos.revision(old)).getBoolean("ok"));assertEquals(old.name,profiles.active().name);String good=stagePhoto(jpeg(64,64));profiles.rename(old.id,"Nome mais novo");assertFalse(commit(old.id,"Nome atrasado",good,LauncherinProfilePhotos.revision(old)).getBoolean("ok"));assertEquals("Nome mais novo",profiles.active().name);assertEquals("",profiles.active().photo);}
 @Test public void overDimensionAndHashMismatchAreRejectedBeforeChangingMetadata()throws Exception{LauncherinMusicProfiles.Profile old=profiles.active();String huge=stagePhoto(jpeg(513,512));assertFalse(commit(old.id,"Troca",huge,LauncherinProfilePhotos.revision(old)).getBoolean("ok"));String hash=stagePhoto(jpeg(100,100));try(FileOutputStream out=new FileOutputStream(LauncherinProfilePhotos.incoming(c,"mp-"+hash.substring(0,40)+".jpg"))){out.write(jpeg(50,50));}assertFalse(commit(old.id,"Troca",hash,LauncherinProfilePhotos.revision(old)).getBoolean("ok"));assertEquals(old.name,profiles.active().name);}
 @Test public void metadataHashPreventsAnotherClientReplacingPendingData()throws Exception{LauncherinProfilePhotos.incoming(c,LauncherinProfilePhotos.PENDING).createNewFile();assertFalse(LauncherinProfilePhotos.call(c,"commitMusicProfile","0".repeat(64)).getBoolean("ok"));assertEquals(2,profiles.list().size());}
 @Test public void addingProfileAndRemovingPhotoNeverDeleteExistingFavoriteData()throws Exception{String id="a".repeat(32),hash=stagePhoto(jpeg(80,80));assertTrue(commit(id,"Novo perfil",hash,"").getBoolean("ok"));LauncherinMusicProfiles.Profile p=profiles.list().get(2);assertTrue(commit(id,p.name,"",LauncherinProfilePhotos.revision(p)).getBoolean("ok"));assertEquals("",profiles.list().get(2).photo);assertFalse(LauncherinProfilePhotos.photo(c,hash).exists());assertEquals("default",profiles.active().id);assertEquals(3,profiles.list().size());}
 @Test public void pathAllowlistAndProfileIdsDoNotAllowArbitraryFiles()throws Exception{for(String name:new String[]{"../config.json","music-profile.apk","mp-foo.jpg","mp-"+"a".repeat(64)+".jpg"})assertFalse(LauncherinProfilePhotos.incoming(name));assertTrue(LauncherinProfilePhotos.incoming("mp-"+"a".repeat(40)+".jpg"));assertFalse(commit("../escape","Nome","","").getBoolean("ok"));assertEquals(2,profiles.list().size());}
 @Test public void sharedPhotoIsPrunedOnlyAfterBothProfilesStopUsingIt()throws Exception{String hash=stagePhoto(jpeg(70,70));LauncherinMusicProfiles.Profile first=profiles.active(),second=profiles.list().get(1);assertTrue(commit(first.id,first.name,hash,LauncherinProfilePhotos.revision(first)).getBoolean("ok"));assertTrue(commit(second.id,second.name,hash,LauncherinProfilePhotos.revision(second)).getBoolean("ok"));first=profiles.active();assertTrue(commit(first.id,first.name,"",LauncherinProfilePhotos.revision(first)).getBoolean("ok"));assertTrue(LauncherinProfilePhotos.photo(c,hash).exists());}
 @Test public void profileLimitAndStatusKeepAnExplicitActiveIdentity()throws Exception{for(int i=0;i<6;i++)profiles.add("Perfil extra "+i);assertFalse(commit("b".repeat(32),"Excesso","","").getBoolean("ok"));Bundle b=LauncherinProfilePhotos.call(c,"musicProfilesStatus");JSONObject j=new JSONObject(b.getString("json"));assertEquals(8,j.getJSONArray("profiles").length());assertEquals("default",j.getString("active"));assertEquals(1,b.getInt("schema"));}
 @Test public void customMenuPreservesOnShowClickAndBackCallbacks(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();boolean[] saved={false};AlertDialog dialog=new LauncherinDialogs.Builder(a).setTitle("Opções da Home").setItems(new String[]{"Opção A","Opção B"},(d,n)->{}).setPositiveButton("Salvar",null).setNegativeButton("Voltar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{saved[0]=true;dialog.dismiss();}));dialog.show();Shadows.shadowOf(Looper.getMainLooper()).idle();assertNotNull(dialog.getWindow().getDecorView());assertTrue(dialog.getListView().isFocusable());dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(saved[0]);assertFalse(dialog.isShowing());a.finish();}
 @Test public void homeMenuUsesThemePaletteWhileMusicHasItsOwnPalette(){LauncherinDialogs.Palette home=new LauncherinDialogs.Palette(c,false),music=new LauncherinDialogs.Palette(c,true);assertEquals(LauncherinAppearance.get(c).accent,home.accent);assertEquals(LauncherinMusicDesign.VIOLET,music.accent);assertTrue(home.panel() instanceof LauncherinSurface);assertNotNull(music.panel());}
 @Test public void manualFullscreenCircleIsLargerAndDoesNotInheritBlackProtector()throws Exception{LauncherinVisualOptions options=new LauncherinVisualOptions(new JSONObject().put("dark",true));LauncherinMusicArtwork images=new LauncherinMusicArtwork(c);LauncherinCircularScreen full=new LauncherinCircularScreen(c,options,images,false,true),normal=new LauncherinCircularScreen(c,options,images,false);try{full.layout(0,0,960,540);normal.layout(0,0,960,540);LauncherinTrack t=LauncherinNativeMusicTest.track(0);full.update(t,-1,false,0,1000);normal.update(t,-1,false,0,1000);assertEquals(View.VISIBLE,full.circle.getVisibility());assertEquals(View.GONE,normal.circle.getVisibility());assertTrue(full.circle.getLayoutParams().width>=490);full.update(t,-1,false,3,1001);assertTrue(full.circle.getLayoutParams().width<=200);}finally{full.release();normal.release();images.close();}}
 @Test public void reducedMotionDoesNotMakeAlbumArtworkNearlyTransparent()throws Exception{LauncherinAppearance.Style old=LauncherinAppearance.get(c);try{org.robolectric.util.ReflectionHelpers.setStaticField(LauncherinAppearance.class,"style",new LauncherinAppearance.Style(c,new JSONObject().put("reduced",true)));LauncherinCircularView visual=new LauncherinCircularView(c,new LauncherinVisualOptions(new JSONObject()));Bitmap b=Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);b.eraseColor(Color.BLUE);visual.cover.setImageBitmap(b);visual.track("new-track");assertEquals(255,visual.cover.getDrawable().getAlpha());assertEquals(1f,visual.cover.getAlpha(),.001f);visual.close();}finally{org.robolectric.util.ReflectionHelpers.setStaticField(LauncherinAppearance.class,"style",old);}}

}
